EXECUTE $dev_active_ddl_419$CREATE TABLE "llm_inference_attempts" (
	"attemptId" varchar(256) PRIMARY KEY NOT NULL,
	"planId" varchar(256) NOT NULL,
	"workerJobAttemptId" varchar(36),
	"attemptOrdinal" smallint NOT NULL,
	"attemptOwnershipEpoch" bigint NOT NULL,
