	"deploymentId" varchar(256) NOT NULL,
	"providerId" varchar(256) NOT NULL,
	"credentialOwnerRef" varchar(256) NOT NULL,
	"endpointSurface" varchar(32) NOT NULL,
	"status" varchar(16) DEFAULT 'prepared' NOT NULL,
	"submissionState" varchar(16) DEFAULT 'not_submitted' NOT NULL,
	"outcome" varchar(16),
	"normalizedFailure" varchar(32),
	"streamCommitted" boolean DEFAULT false NOT NULL,
	"providerRequestId" varchar(256),
	"gatewayRequestId" varchar(256),
	"observedProviderId" varchar(256),
	"observedCredentialOwnerRef" varchar(256),
	"observedDeploymentId" varchar(256),
	"observedEndpointSurface" varchar(32),
	"inputTokens" bigint,
	"cachedInputTokens" bigint,
	"outputTokens" bigint,
	"reasoningTokens" bigint,
	"chargedCostMicros" bigint,
	"effectReceiptRefsJson" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"createdAt" timestamp with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	"terminalAt" timestamp with time zone,
	CONSTRAINT "llm_inference_attempts_ordinal_check" CHECK ("llm_inference_attempts"."attemptOrdinal" BETWEEN 1 AND 16),
	CONSTRAINT "llm_inference_attempts_epoch_check" CHECK ("llm_inference_attempts"."attemptOwnershipEpoch" > 0),
	CONSTRAINT "llm_inference_attempts_endpoint_surface_check" CHECK ("llm_inference_attempts"."endpointSurface" IN ('native_responses', 'responses_compatible', 'chat_compatible', 'native_provider', 'local')),
	CONSTRAINT "llm_inference_attempts_status_check" CHECK ("llm_inference_attempts"."status" IN ('prepared', 'submitting', 'submitted', 'terminal')),
	CONSTRAINT "llm_inference_attempts_submission_state_check" CHECK ("llm_inference_attempts"."submissionState" IN ('not_submitted', 'submitted', 'unknown')),
	CONSTRAINT "llm_inference_attempts_outcome_check" CHECK ("llm_inference_attempts"."outcome" IS NULL OR "llm_inference_attempts"."outcome" IN ('completed', 'failed', 'cancelled', 'unknown')),
	CONSTRAINT "llm_inference_attempts_failure_check" CHECK ("llm_inference_attempts"."normalizedFailure" IS NULL OR "llm_inference_attempts"."normalizedFailure" IN ('rate_limited', 'provider_unavailable', 'connection_failed', 'authentication_failed', 'invalid_request', 'content_policy', 'budget_exceeded', 'unknown_outcome')),
	CONSTRAINT "llm_inference_attempts_usage_check" CHECK (COALESCE("llm_inference_attempts"."inputTokens", 0) >= 0 AND COALESCE("llm_inference_attempts"."cachedInputTokens", 0) >= 0 AND COALESCE("llm_inference_attempts"."outputTokens", 0) >= 0 AND COALESCE("llm_inference_attempts"."reasoningTokens", 0) >= 0 AND COALESCE("llm_inference_attempts"."chargedCostMicros", 0) >= 0),
	CONSTRAINT "llm_inference_attempts_state_consistency_check" CHECK (("llm_inference_attempts"."status" = 'prepared' AND "llm_inference_attempts"."submissionState" = 'not_submitted' AND "llm_inference_attempts"."outcome" IS NULL AND "llm_inference_attempts"."terminalAt" IS NULL) OR ("llm_inference_attempts"."status" = 'submitting' AND "llm_inference_attempts"."submissionState" = 'unknown' AND "llm_inference_attempts"."outcome" IS NULL AND "llm_inference_attempts"."terminalAt" IS NULL) OR ("llm_inference_attempts"."status" = 'submitted' AND "llm_inference_attempts"."submissionState" = 'submitted' AND "llm_inference_attempts"."outcome" IS NULL AND "llm_inference_attempts"."terminalAt" IS NULL) OR ("llm_inference_attempts"."status" = 'terminal' AND "llm_inference_attempts"."outcome" IS NOT NULL AND "llm_inference_attempts"."terminalAt" IS NOT NULL)),
	CONSTRAINT "llm_inference_attempts_stream_submission_check" CHECK (NOT "llm_inference_attempts"."streamCommitted" OR "llm_inference_attempts"."submissionState" = 'submitted'),
	CONSTRAINT "llm_inference_attempts_observed_identity_check" CHECK (("llm_inference_attempts"."observedProviderId" IS NULL AND "llm_inference_attempts"."observedCredentialOwnerRef" IS NULL AND "llm_inference_attempts"."observedDeploymentId" IS NULL AND "llm_inference_attempts"."observedEndpointSurface" IS NULL) OR ("llm_inference_attempts"."observedProviderId" IS NOT NULL AND "llm_inference_attempts"."observedCredentialOwnerRef" IS NOT NULL AND "llm_inference_attempts"."observedDeploymentId" IS NOT NULL AND "llm_inference_attempts"."observedEndpointSurface" IS NOT NULL AND "llm_inference_attempts"."observedEndpointSurface" IN ('native_responses', 'responses_compatible', 'chat_compatible', 'native_provider', 'local')))
);$dev_active_ddl_419$;
