	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	"settledAt" timestamp with time zone,
	CONSTRAINT "skill_revenue_debts_amounts_valid" CHECK ("skill_revenue_debts"."amount" >= 0 AND "skill_revenue_debts"."recoveredCredits" >= 0 AND "skill_revenue_debts"."recoveredCredits" <= "skill_revenue_debts"."amount")
);$dev_active_ddl_583$;
EXECUTE $dev_active_ddl_584$CREATE TABLE "skill_revenue_settlements" (
	"id" serial PRIMARY KEY NOT NULL,
	"runId" text NOT NULL,
	"skillId" integer,
	"skillSlug" varchar(128) NOT NULL,
	"tenantId" varchar(36),
	"userId" integer NOT NULL,
	"tenantOwnerId" integer,
	"skillOwnerId" integer,
	"tenantCredits" integer DEFAULT 0 NOT NULL,
	"skillOwnerCredits" integer DEFAULT 0 NOT NULL,
	"totalCredits" integer DEFAULT 0 NOT NULL,
	"configuredTotalCredits" integer DEFAULT 0 NOT NULL,
	"actualWorkCredits" integer,
	"chargedTotalCredits" integer DEFAULT 0 NOT NULL,
	"pricingSource" varchar(64) DEFAULT 'skill_config' NOT NULL,
	"capApplied" boolean DEFAULT false NOT NULL,
	"userTransactionId" integer,
	"tenantRevenueTransactionId" integer,
	"skillRevenueTransactionId" integer,
	"status" "skill_revenue_settlement_status" DEFAULT 'settled' NOT NULL,
	"reversedAt" timestamp with time zone,
	"createdAt" timestamp with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "skill_revenue_settlements_amounts_non_negative" CHECK ("skill_revenue_settlements"."tenantCredits" >= 0 AND "skill_revenue_settlements"."skillOwnerCredits" >= 0 AND "skill_revenue_settlements"."totalCredits" >= 0),
	CONSTRAINT "skill_revenue_settlements_total_matches_split" CHECK ("skill_revenue_settlements"."totalCredits" = "skill_revenue_settlements"."tenantCredits" + "skill_revenue_settlements"."skillOwnerCredits"),
	CONSTRAINT "skill_revenue_settlements_charge_audit_non_negative" CHECK ("skill_revenue_settlements"."configuredTotalCredits" >= 0 AND "skill_revenue_settlements"."chargedTotalCredits" >= 0 AND ("skill_revenue_settlements"."actualWorkCredits" IS NULL OR "skill_revenue_settlements"."actualWorkCredits" >= 0)),
	CONSTRAINT "skill_revenue_settlements_charge_does_not_exceed_config" CHECK ("skill_revenue_settlements"."chargedTotalCredits" <= "skill_revenue_settlements"."configuredTotalCredits"),
	CONSTRAINT "skill_revenue_settlements_charge_does_not_exceed_work" CHECK ("skill_revenue_settlements"."actualWorkCredits" IS NULL OR "skill_revenue_settlements"."chargedTotalCredits" <= "skill_revenue_settlements"."actualWorkCredits"),
	CONSTRAINT "skill_revenue_settlements_charge_matches_total" CHECK ("skill_revenue_settlements"."chargedTotalCredits" = "skill_revenue_settlements"."totalCredits")
);$dev_active_ddl_584$;
